mapper.select:
SELECT p.*, c.category_name AS categoryName
FROM agri_md_product p
LEFT JOIN agri_md_product_category c ON p.category_id = c.id
WHERE p.del_flag = 0

    AND p.product_code LIKE CONCAT('%', #{dto.productCode}, '%')


    AND p.product_name LIKE CONCAT('%', #{dto.productName}, '%')


    AND p.category_id = #{dto.categoryId}


    AND p.status = #{dto.status}

ORDER BY p.create_time DESC
LIMIT #{dto.pageNum}, #{dto.pageSize}

SELECT COUNT(*) FROM agri_md_product p WHERE p.del_flag = 0
AND p.product_code LIKE CONCAT('%', #{dto.productCode}, '%')
AND p.product_name LIKE CONCAT('%', #{dto.productName}, '%')
AND p.category_id = #{dto.categoryId}
AND p.status = #{dto.status}
